const EditProfile = ({ user }) => {
  const [name, setName] = useState(user.name); // 只在首次渲染取值
  const save = () => updateUser(user.id, { name });
  return (
    <form onSubmit={save}>
      <input value={name} onChange={(e) => setName(e.target.value)} />
      <button type="submit">Save</button>
    </form>
  );
};

const TodoList = ({ todos }) => {
  const [hideDone, setHideDone] = useState(false);
  const [visible, setVisible] = useState(todos); // 把过滤结果存成了 state

  return (
    <>
      <label>
        <input
          type="checkbox"
          checked={hideDone}
          onChange={(e) => setHideDone(e.target.checked)}
        />
        Hide completed
      </label>
      {visible.map((t) => (
        <Row key={t.id} todo={t} />
      ))}
    </>
  );
};

const Rows = ({ items }) => (
  <ul>
    {items.map((item, index) => (
      <Row key={index} item={item} /> // 用下标当 key
    ))}
  </ul>
);

// Row 内部有本地输入状态
const Row = ({ item }) => {
  const [text, setText] = useState(item.label);
  return (
    <li>
      <input value={text} onChange={(e) => setText(e.target.value)} />
    </li>
  );
};

